contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 val) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0, "no ether required");
        uint256 beforeBal = address(c).balance;
        bool reverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 afterVal = c.MinSum(); if (__ESBMC_reverted()) return;
        uint256 afterBal = address(c).balance;
        assert(!reverted && afterVal == val && afterBal == beforeBal);
    }
}

